def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    for pair in history:
        if pair[1] == 'C':
            opp_c += 1
    opp_rate = opp_c / float(n)

    c_after_c = 0
    d_after_c = 0
    c_after_d = 0
    d_after_d = 0
    for i in range(n - 1):
        m = history[i][0]
        o = history[i + 1][1]
        if m == 'C':
            if o == 'C':
                c_after_c += 1
            else:
                d_after_c += 1
        else:
            if o == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

    total_c = c_after_c + d_after_c
    total_d = c_after_d + d_after_d

    if total_c > 0:
        p_c = c_after_c / float(total_c)
    else:
        p_c = opp_rate

    if total_d > 0:
        p_d = c_after_d / float(total_d)
    else:
        p_d = None

    same_opp = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_opp += 1
        else:
            break

    if opp_last == 'D':
        streak_opp_D = same_opp
        streak_opp_C = 0
    else:
        streak_opp_D = 0
        streak_opp_C = same_opp

    recent_start = n - 5
    if recent_start < 0:
        recent_start = 0

    recent_opp_c = 0
    for i in range(recent_start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_len = n - recent_start

    can_exploit = False
    if total_d > 0 and recent_opp_c >= 3 and recent_len >= 4 and opp_rate >= 0.35:
        if total_d == 1:
            if p_d >= 0.85:
                can_exploit = True
        elif total_d == 2:
            if p_d >= 0.70:
                can_exploit = True
        else:
            if p_d >= 0.60:
                can_exploit = True
            elif total_d >= 4 and p_d >= 0.50 and p_c <= p_d + 0.25:
                can_exploit = True

        if my_last == 'D' and opp_last == 'D' and streak_opp_D >= 3:
            can_exploit = False

    if can_exploit:
        return 'D'

    if my_last == 'D' and opp_last == 'C' and opp_rate >= 0.25:
        return 'C'

    if opp_last == 'C' and opp_rate >= 0.65 and streak_opp_C >= 3 and n < 97:
        prob = 0.0
        if total_d == 0:
            if streak_opp_C >= 3:
                prob = 0.35
        else:
            if streak_opp_C >= 8:
                prob = 0.03
            if streak_opp_C >= 16:
                prob = 0.07
            if streak_opp_C >= 30:
                prob = 0.05

        if prob > 0.0 and rng.random() < prob:
            return 'D'

    if opp_last == 'D':
        if p_c < 0.18 or opp_rate < 0.12:
            return 'D'

        if opp_rate < 0.30 and p_c < 0.55:
            return 'D'

        if total_d > 0 and total_c > 0 and opp_rate >= 0.35:
            if p_d >= 0.45 and p_c <= p_d + 0.15:
                return 'D'

        if streak_opp_D >= 8:
            if opp_rate > 0.25 and rng.random() < 0.08:
                return 'C'
            return 'D'

        if p_c >= 0.52 or opp_rate >= 0.55:
            return 'C'

        if p_c >= 0.32 and streak_opp_D <= 2:
            return 'C'

        return 'D'

    return 'C'
